if(getPref('dark')==='1')document.body.classList.add('dark');removePref('font_scale');removePref('large_text');document.body.classList.remove('large-text');syncThemeModeButton();removePref('accent');removePref('accent2');removePref('soft');removePref('theme_name');applyAccent('#89546F','#EEDFE7');document.documentElement.style.setProperty('--accent2','#B77F9D');authOverlay();
